
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_op_pw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_op_pw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.897782754460728e-02, -5.866841032783760e-02, -5.821236581509018e-02, -5.753339330529220e-02, -5.650850563798263e-02, -5.493339136939306e-02, -5.246066150730463e-02, -4.850757827766710e-02, -4.224372778358457e-02, -3.341046362288996e-02, -2.585739265886669e-02, -2.944416783517089e-02, -3.522796556529096e-02, -2.783730023791697e-02, -1.730783307095270e-02, -7.519970851972495e-03, -4.688408513463481e-03, -1.276712014971992e-01, -4.900437470731932e+01, -5.853632738874278e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


